export const AFFIX_MAP=new Map(AFFIX_DEFINITIONS.map(a=>[a.id,a]));
export const affixKind=a=>AFFIX_MAP.get(a.id)?.kind??'stat';
export const eligibleAffixes=(family,kind)=>AFFIX_DEFINITIONS.filter(d=>!d.legacy&&d.kind===kind&&(!d.families||d.families.includes(family)));
export function compatibleAffix(def,others){return !others.some(a=>a.id===def.id||def.conflicts?.includes(a.id)||AFFIX_MAP.get(a.id)?.conflicts?.includes(def.id));}
export function behaviorModifiers(w){
 const m={range:1,arc:1,area:1,damage:1,contact:1,width:1,spread:1,turn:1,projectileFactor:1,extra:0,pierce:0,push:0,pull:0,echo:0,beams:1,beamPierce:1,staggerAdd:0};
 for(const def of AFFIX_DEFINITIONS)if(def.kind==='behavior'&&w.affixes.some(a=>a.id===def.id))for(const [key,value]of Object.entries(def.mods)){
   if(['range','arc','area','damage','contact','width','spread','turn','projectileFactor'].includes(key))m[key]*=value;
   else if(['extra','pierce','push','pull','staggerAdd'].includes(key))m[key]+=value;else m[key]=value;
 }return m;
}
